  'v2.alertTitle': { en: 'Not ready to decide?', es: '¿Aún no ha decidido?', fr: 'Pas encore décidé ?', de: 'Noch nicht entschieden?', ru: 'Ещё не решили?', ar: 'لم تقرر بعد؟', nl: 'Nog niet zeker?', pl: 'Jeszcze się Państwo zastanawiają?', sv: 'Inte redo att bestämma er?', no: 'Ikke klar til å bestemme deg?' },
  'v2.alertBody': { en: 'We’ll email you if a home here is reserved, comes back, or changes price. Nothing else.', es: 'Le escribiremos si una vivienda se reserva, vuelve a estar disponible o cambia de precio. Nada más.', fr: 'Nous vous écrirons si un bien est réservé, redevient disponible ou change de prix. Rien d’autre.', de: 'Wir schreiben Ihnen, wenn eine Wohnung reserviert wird, wieder frei wird oder ihren Preis ändert. Sonst nichts.', ru: 'Мы напишем вам, если объект забронируют, он снова освободится или изменится цена. Больше ничего.', ar: 'سنراسلك إذا حُجزت وحدة هنا أو عادت متاحة أو تغيّر سعرها. لا شيء غير ذلك.', nl: 'Wij mailen u als een woning hier wordt gereserveerd, weer vrijkomt of van prijs verandert. Verder niets.', pl: 'Napiszemy do Państwa, gdy nieruchomość zostanie zarezerwowana, wróci do sprzedaży lub zmieni cenę. Nic więcej.', sv: 'Vi mejlar er om en bostad här reserveras, blir ledig igen eller ändrar pris. Inget annat.', no: 'Vi sender deg en e-post hvis en bolig her blir reservert, blir ledig igjen eller endrer pris. Ikke noe annet.' },
  'v2.alertButton': { en: 'Alert me', es: 'Avisarme', fr: 'M’alerter', de: 'Benachrichtigen', ru: 'Сообщить мне', ar: 'نبّهني', nl: 'Houd me op de hoogte', pl: 'Powiadom mnie', sv: 'Meddela mig', no: 'Varsle meg' },
  'v2.alertConsent': { en: 'I agree that Nueva Living may email me about this development.', es: 'Acepto que Nueva Living me escriba sobre esta promoción.', fr: 'J’accepte que Nueva Living m’écrive au sujet de ce programme.', de: 'Ich bin einverstanden, dass Nueva Living mir zu diesem Projekt schreibt.', ru: 'Я согласен(на) получать от Nueva Living письма об этом проекте.', ar: 'أوافق على أن تراسلني Nueva Living بشأن هذا المشروع.', nl: 'Ik ga ermee akkoord dat Nueva Living mij over dit project mailt.', pl: 'Wyrażam zgodę na wiadomości e-mail od Nueva Living dotyczące tej inwestycji.', sv: 'Jag godkänner att Nueva Living mejlar mig om det här projektet.', no: 'Jeg godtar at Nueva Living sender meg e-post om dette prosjektet.' },
  'v2.alertSending': { en: 'Sending…', es: 'Enviando…', fr: 'Envoi…', de: 'Wird gesendet…', ru: 'Отправка…', ar: 'جارٍ الإرسال…', nl: 'Verzenden…', pl: 'Wysyłanie…', sv: 'Skickar…', no: 'Sender…' },
  'v2.alertDone': { en: 'Done. We’ll email you if availability or prices change.', es: 'Hecho. Le escribiremos si cambia la disponibilidad o los precios.', fr: 'C’est noté. Nous vous écrirons si la disponibilité ou les prix changent.', de: 'Erledigt. Wir schreiben Ihnen, wenn sich Verfügbarkeit oder Preise ändern.', ru: 'Готово. Мы напишем вам, если изменятся наличие или цены.', ar: 'تم. سنراسلك إذا تغيّر التوفر أو الأسعار.', nl: 'Gelukt. Wij mailen u als de beschikbaarheid of de prijzen veranderen.', pl: 'Gotowe. Napiszemy, gdy zmieni się dostępność lub ceny.', sv: 'Klart. Vi mejlar er om tillgänglighet eller priser ändras.', no: 'Ferdig. Vi sender deg en e-post hvis tilgjengelighet eller priser endres.' },
  'v2.alertError': { en: 'That did not go through. Please try again, or message us on WhatsApp.', es: 'No se ha podido enviar. Inténtelo de nuevo o escríbanos por WhatsApp.', fr: 'L’envoi a échoué. Veuillez réessayer ou nous écrire sur WhatsApp.', de: 'Das hat nicht geklappt. Bitte versuchen Sie es erneut oder schreiben Sie uns auf WhatsApp.', ru: 'Не удалось отправить. Попробуйте ещё раз или напишите нам в WhatsApp.', ar: 'تعذّر الإرسال. يُرجى المحاولة مجدداً أو مراسلتنا عبر واتساب.', nl: 'Dat is niet gelukt. Probeer het opnieuw of stuur ons een bericht via WhatsApp.', pl: 'Nie udało się wysłać. Prosimy spróbować ponownie lub napisać do nas na WhatsAppie.', sv: 'Det gick inte att skicka. Försök igen eller skriv till oss på WhatsApp.', no: 'Det gikk ikke. Prøv igjen, eller send oss en melding på WhatsApp.' },
  'v2.alertMessage': { en: 'Please tell me if availability or prices change at {name}.', es: 'Avísenme si cambia la disponibilidad o los precios en {name}.', fr: 'Merci de me prévenir si la disponibilité ou les prix changent à {name}.', de: 'Bitte informieren Sie mich, wenn sich Verfügbarkeit oder Preise bei {name} ändern.', ru: 'Сообщите мне, если в {name} изменятся наличие или цены.', ar: 'يُرجى إبلاغي إذا تغيّر التوفر أو الأسعار في {name}.', nl: 'Laat het me weten als de beschikbaarheid of de prijzen bij {name} veranderen.', pl: 'Proszę o informację, jeśli zmieni się dostępność lub ceny w {name}.', sv: 'Meddela mig om tillgänglighet eller priser ändras i {name}.', no: 'Gi meg beskjed hvis tilgjengelighet eller priser endres i {name}.' },
